"""One-time narrowly scoped synchronization of the 2026-10-12 routing decision."""
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent

def update(name, replacements):
    path=ROOT/'01.docs'/name
    text=path.read_text(encoding='utf-8-sig')
    for old,new,count in replacements:
        assert text.count(old)==count, (name,old,text.count(old),count)
        text=text.replace(old,new)
    with path.open('w',encoding='utf-8',newline='') as f:
        f.write(text.replace('\n','\r\n'))
    print(name, len(replacements), 'targeted replacements')

